const body = $input.first().json.body || {};

// Vérifier les champs requis
const hasFile = !!(body.file_url || body.file_base64);
const hasAction = !!body.action;

if (!hasFile || !hasAction) {
  return {
    json: {
      valid: false,
      can_proceed: false,
      missing: [
        ...(!hasFile ? ['file'] : []),
        ...(!hasAction ? ['action'] : [])
      ],
      errors: [
        ...(!hasFile ? ['Document requis (file_url ou file_base64)'] : []),
        ...(!hasAction ? ['Action requise (translate, summarize, etc.)'] : [])
      ],
      questions: []
    }
  };
}

const action = body.action;
const params = body.params || {};
const pluginContext = body.plugin_context || {};
const availableActions = pluginContext.available_actions || ['translate', 'summarize'];
const requiredParams = pluginContext.required_params || {
  translate: ['target_language'],
  summarize: ['format']
};
const customActions = pluginContext.custom_actions || {};

// Vérifier si l'action est valide
const isStandardAction = availableActions.includes(action);
const isCustomAction = Object.keys(customActions).includes(action);

if (!isStandardAction && !isCustomAction) {
  return {
    json: {
      valid: false,
      can_proceed: false,
      missing: [],
      errors: [`Action '${action}' non disponible. Actions valides: ${[...availableActions, ...Object.keys(customActions)].join(', ')}`],
      questions: []
    }
  };
}

// Récupérer les params requis pour cette action
const finalRequiredParams = customActions[action]?.required_params || requiredParams[action] || [];

// Questions prédéfinies par paramètre
const paramQuestions = {
  target_language: {
    question: 'Dans quelle langue veux-tu la traduction ?',
    type: 'text',
    examples: 'français, anglais, espagnol...'
  },
  format: {
    question: 'Quel format de synthèse souhaites-tu ?',
    type: 'choice',
    options: [
      { value: 'express', label: 'Résumé express (2-3 phrases)' },
      { value: 'points', label: 'Points clés (liste à puces)' },
      { value: 'structured', label: 'Résumé structuré (paragraphes)' },
      { value: 'outline', label: 'Plan détaillé (hiérarchique)' },
      { value: 'focused', label: 'Extraction ciblée (vous précisez)' }
    ]
  },
  output_format: {
    question: 'Quel format de sortie ?',
    type: 'choice',
    options: [
      { value: 'json', label: 'JSON structuré' },
      { value: 'list', label: 'Liste texte' }
    ]
  },
  target_system: {
    question: 'Vers quel système convertir les unités ?',
    type: 'choice',
    options: [
      { value: 'metric', label: 'Métrique (g, ml, °C)' },
      { value: 'imperial', label: 'Impérial (oz, cups, °F)' }
    ]
  },
  servings: {
    question: 'Pour combien de personnes ?',
    type: 'number',
    default: 4
  }
};

const missing = [];
const questions = [];

// Vérifier chaque paramètre requis
for (const param of finalRequiredParams) {
  if (!params[param] || params[param] === '') {
    missing.push(param);
    questions.push({
      param: param,
      ...(paramQuestions[param] || {
        question: `Veuillez fournir: ${param}`,
        type: 'text'
      })
    });
  }
}

return {
  json: {
    valid: missing.length === 0,
    can_proceed: missing.length === 0,
    missing: missing,
    errors: [],
    questions: questions,
    action: action,
    params: params,
    is_custom_action: isCustomAction,
    custom_webhook_url: customActions[action]?.webhook_url || null
  }
};
